return ['domain'=>'publishpress-statuses-pro% 10 == 0) ? 2 : 3)));% 10 == 0) ? 2: 3)));','plural-forms'=>'nplurals=4; plural=(n == 1 ? 0 : (n == 2 ? 1 : ((n > 10 && n % 10 == 0) ? 2 : 3)));','language'=>'he_IL','project-id-version'=>'PublishPress Statuses Pro 1.3.1-beta','pot-creation-date'=>'2026-04-29T19:59:23+00:00','po-revision-date'=>'2026-09-02 21:48+0000','x-generator'=>'WP-CLI 2.13.0-alpha','messages'=>['PublishPress Statuses Pro'=>'PublishPress Statuses Pro','https://publishpress.com/statuses'=>'https://publishpress.com/statuses','Manage and create post statuses to customize your editorial workflow'=>'נהל וצור סטטוסים לפוסטים כדי להתאים את זרימת העבודה העריכתית שלך','PublishPress'=>'PublishPress','https://publishpress.com/'=>'https://publishpress.com/','New Revision created'=>'גרסה חדשה נוצרה','Revision is submitted'=>'הגרסה הוגשה','Revision deferred or rejected'=>'הגרסה נדחתה או הושעתה','Revision is scheduled'=>'הגרסה מתוכננת','Scheduled Revision published'=>'הגרסה המתוכננת פורסמה','Post status changed'=>'סטטוס הפוסט השתנה','Post deferred or rejected'=>'הפוסט נדחה או בוטל','Revision Status'=>'סטטוס גרסה','Drop any status here to include it in main workflow for post revisions.'=>'שחרר כל סטטוס כאן כדי לכלול אותו בזרימת העבודה העיקרית של תיקונים.','Drop any status here to make it manually selectable outside the main revision workflow.'=>'הנח כל סטטוס כאן כדי להפוך אותו לבחירה ידנית מחוץ לזרימת העבודה הראשית של גרסה.','Add New Visibility Status'=>'הוסף סטטוס נראות חדש','Add New Revision Status'=>'הוסף סטטוס תיקון חדש','This status can be assigned to a post as a different form of Private Publication with its own capability requirements.'=>'סטטוס זה יכול להיות משויך לפוסט כאופציה שונה של פרסום פרטי עם דרישות יכולת משלו.','This status can be assigned to revisions of published posts.'=>'סטטוס זה ניתן להקצה לתיקונים של פוסטים שפורסמו.','Revision Statuses'=>'סטטוסי גרסה','Main Revision Workflow:'=>'זרימת עבודה עיקרית של תיקון:','Alternate Revision Workflow:'=>'זרימת עבודה חלופית של תיקון:','Revision Deferred'=>'תיקון נדחה','Defer'=>'לדחות','Revision has been deferred for future consideration.'=>'התיקון נדחה לשקילה עתידית.','Revision Needs Work'=>'התיקון דורש עבודה','Set to Needs Work'=>'הגדר לדרוש עבודה','Revision needs work before further review.'=>'התיקון דורש עבודה לפני סקירה נוספת.','Change Deferred'=>'שינוי נדחה','Change has been deferred for future consideration.'=>'השינוי נדחה לשקילה עתידית.','Change Needs Work'=>'השינוי דורש עבודה','Change needs work before further review.'=>'השינוי דורש עבודה לפני סקירה נוספת.','To use PublishPress Statuses, please upgrade PublishPress Planner to version %s or higher.'=>'כדי להשתמש ב-PublishPress Statuses, אנא עדכן את PublishPress Planner לגרסה %s או גבוה יותר.','To use PublishPress Statuses, please upgrade PublishPress Permissions Pro to version %s or higher.'=>'כדי להשתמש ב-PublishPress Statuses, אנא עדכן את PublishPress Permissions Pro לגרסה %s או גבוה יותר.','To use PublishPress Statuses, please upgrade PublishPress Capabilities Pro to version %s or higher.'=>'כדי להשתמש ב-PublishPress Statuses, אנא עדכן את PublishPress Capabilities Pro לגרסה %s או גבוה יותר.','%sYour license key has expired%s. For continued priority support, %splease renew%s.'=>'%sמפתח הרישוי שלך פג תוקף%s. כדי להמשיך לקבל תמיכה עדיפה, %sאנא renouvel%s.','%sYour license key will expire today%s. For updates and priority support, %splease renew%s.'=>'%sמפתח הרישוי שלך יפוג היום%s. עבור עדכונים ותמיכה עדיפה, %sאנא renouvel%s.','%sYour license key (for plugin updates) will expire in %d days%s. For updates and priority support, %splease renew%s.'=>'%sמפתח הרישוי שלך (לעדכוני תוסף) יפוג בעוד %d ימים%s. עבור עדכונים ותמיכה עדיפה, %sאנא renouvel%s.','For updates to PublishPress Statuses Pro, activate your %sPublishPress license key%s.'=>'עבור עדכונים ל-PublishPress Statuses Pro, הפעל את %sמפתח הרישוי של PublishPress%s.','Deactivate Key'=>'בטל הפעלת מפתח','Key Expired'=>'המפתח פג תוקף','Activate Key'=>'הפעל מפתח','Key Ac